using Acme.Inventory;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddHttpClient<InventoryClient>(c => c.BaseAddress = new Uri("https://inventory.example.com/"));

var app = builder.Build();

app.MapGet("/stock/{sku}", async (string sku, InventoryClient inventory, CancellationToken ct) =>
    await inventory.GetStockAsync(sku, ct) is { } stock
        ? Results.Ok(stock)
        : Results.NotFound());

app.Run();

using System.Net.Http.Json;

namespace Acme.Inventory;

public sealed class InventoryClient(HttpClient http)
{
    public async Task<StockLevel?> GetStockAsync(string sku, CancellationToken ct)
    {
        for (var attempt = 1; ; attempt++)
        {
            try
            {
                return await http.GetFromJsonAsync<StockLevel>($"v2/stock/{Uri.EscapeDataString(sku)}", ct);
            }
            catch (HttpRequestException) when (attempt < 3)
            {
                await Task.Delay(500, ct);
            }
        }
    }
}

public sealed record StockLevel(string Sku, int Available);

